fn input(p:&Path)->Inputs{let manifest=p.join("logs/continuation-20261003/r486-map-binding.json");let b=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:b.len()as u64,sha256:Sha256::digest(b).into()}}}
fn wait(mut f:impl FnMut()->bool){let end=Instant::now()+Duration::from_secs(60);while !f(){assert!(Instant::now()<end,"R492 bounded lifecyclecandidate wait");thread::sleep(Duration::from_millis(2));}}
fn packet(v:&Value)->Vec<u8>{v.as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect()}
fn source(rt:&Runtime)->Value{let f=rt.source_flow();json!({"phase":f.phase(),"dispatch":f.dispatch_word(),"identifier":f.mode().identifier(),"mode":f.mode().raw_mode(),"raw":f.snapshot().map(|s|s.raw().to_vec()),"source_epoch":rt.source_connection_epoch()})}
fn state(rt:&Runtime)->Value{json!({"source":source(rt),"generation":rt.generation(),"page":format!("{:?}",rt.page()),"status":rt.status(),"menu":rt.menu().map(|m|json!({"filter":format!("{:?}",m.filter),"count":m.count(),"top":m.top,"selected":m.selected,"pressed":format!("{:?}",m.pressed),"repeat":m.repeat_deadline()})),"choice":rt.choice().map(|c|(c.mode,c.map_id)),"frame":rt.frame().map(|f|f.identity())})}
fn empty(rt:&Runtime,epoch:Option<u64>){assert_eq!((rt.source_flow().phase(),rt.source_flow().dispatch_word(),rt.source_flow().mode().identifier(),rt.source_flow().mode().raw_mode()),(0,0,0,0));assert!(rt.source_flow().snapshot().is_none());assert_eq!(rt.source_connection_epoch(),epoch);let m=rt.menu().unwrap();assert_eq!((m.count(),m.top,m.selected,m.pressed,m.repeat_deadline()),(0,0,None,None,None));assert!(rt.choice().is_none()&&rt.frame().is_none());}
fn begin(rt:&mut Runtime)->anyhow::Result<Epoch>{let g=rt.generation();let e=rt.begin_source_connection_candidate()?;assert_eq!(rt.generation(),g+1);empty(rt,Some(e.serial()));let before=state(rt);assert!(rt.handle_player_command(SOURCE_MENU_COMMAND_ID).is_err());assert_eq!(state(rt),before);Ok(e)}
fn consume(rt:&mut Runtime,epoch:&Epoch,body:&[u8])->anyhow::Result<()>{let e=epoch.decoded_packet(body)?;assert_eq!(e.body(),body);assert_eq!(e.epoch_serial(),epoch.serial());assert!(rt.consume_source_event(&e)?.clear_map_list);assert_eq!(rt.source_flow().phase(),2);Ok(())}
fn open(rt:&mut Runtime,mode:u8)->anyhow::Result<()>{let s=source(rt);rt.handle_player_command(SOURCE_MENU_COMMAND_ID)?;assert_eq!(source(rt),s);assert_eq!(rt.menu().unwrap().filter,Filter::Mode{mode,alternate:false});Ok(())}
fn active(rt:&mut Runtime)->anyhow::Result<()>{rt.handle(Action::Select(3,563))?;thread::sleep(Duration::from_millis(10));rt.handle(Action::Enter)?;wait(||rt.progress().load_active.load(Ordering::Acquire));Ok(())}
